policies.shadow:
version: 1
classify:
  area:
    docs: ["docs/**"]
    web: ["web/**"]
    auth: ["**/auth/**"]
rules:
  - { name: strict-docs, when: { area: docs }, action: human_approve, reason: "Trying stricter docs review.", mode: shadow }
  - { name: block-web, when: { area: web }, action: block, reason: "Trial web freeze.", shadow: true }
  - { name: docs, when: { area: docs }, action: auto_merge, reason: "Routine docs change." }
  - { name: auth-agrees, when: { area: auth }, action: human_approve, reason: "Same as the enforced auth rule.", mode: shadow }
  - { name: auth, when: { area: auth }, action: human_approve, reason: "Auth is a security boundary.", mode: enforce }
  - { name: late-docs, when: { area: docs }, action: block, reason: "Comes after the deciding rule.", mode: shadow }
default: { action: agent_review, reason: "Fallback." }

policies.invalid:
version: 1
rules:
  - { whne: { area: docs }, action: auto_merge, reason: r }

policies.only:
version: 1
classify:
  area:
    docs: ["docs/**", "**/*.md"]
    tests: ["**/*_test.go"]
    app: ["internal/**"]
rules:
  - { name: docs-only, when: { only_area: docs }, action: auto_merge, reason: "Every file is docs." }
  - { name: tests-only, when: { only_area: tests }, action: agent_review, reason: "Every file is a test." }
default: { action: human_approve, reason: "A person decides." }

policies.bad-action:
version: 1
rules:
  - { when: { risk: low }, action: approve, reason: r }

policies.dup-key:
version: 1
default: { action: block, reason: r }
default: { action: auto_merge, reason: r }

policies.multi:
version: 1
classify:
  area: { infra: [".github/**"] }
rules:
  - { when: { area: infra }, action: multi_approve, reason: "Infra needs two." }

policies.ai:
version: 1
classify:
  area:
    tests: ["**/*_test.go"]
    docs: ["docs/**"]
    web: ["web/**"]
rules:
  - { name: tests-ai, when: { only_area: tests }, action: agent_review, reviewer: ai, ai: { min_confidence: 0.8, model: "@cf/meta/llama-4-scout-17b-16e-instruct" }, reason: "Tests only; the AI reviewer decides, confidently." }
  - { name: docs-agent, when: { only_area: docs }, action: agent_review, reviewer: { kind: agent, different_family: true }, reason: "Docs get a reviewer agent from another family." }
  - { name: web-advised, when: { area: web }, action: human_approve, ai: { advise: true, model: "anthropic/claude-sonnet-5.5" }, reason: "A person decides, with AI advice." }
default: { action: human_approve, ai: { advise: true }, reason: "A person decides, with AI advice." }

policies.no-binary:
version: 1
classify:
  area:
    docs: ["docs/**"]
binary: { allow: [] }
rules:
  - { name: docs, when: { area: docs }, action: auto_merge, reason: "Routine docs change." }
default: { action: human_approve, reason: "A person decides." }
